"""URL slugs."""
import re


def slugify(text):
    """Lowercase words joined by single hyphens, with no leading or trailing hyphen."""
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")

import unittest

from slug import slugify


class SlugifyTests(unittest.TestCase):
    def test_no_trailing_hyphen(self):
        self.assertEqual(slugify("Hello, World!"), "hello-world")

    def test_no_leading_hyphen(self):
        self.assertEqual(slugify("  Already  spaced  "), "already-spaced")

    def test_repeated_separators_collapse(self):
        self.assertEqual(slugify("a--b"), "a-b")


if __name__ == "__main__":
    unittest.main()
